#!/usr/bin/env python3
from pathlib import Path

p = Path("source/src/video.cpp")
s = p.read_text()

include_anchor = '#include <array>\n#include <atomic>\n#include <bitset>\n#include <list>\n#include <thread>\n'
include_repl = '''#include <array>\n#include <atomic>\n#include <bitset>\n#include <list>\n#include <map>\n#include <memory>\n#include <thread>\n\n#ifdef __aarch64__\n  #include <arm_neon.h>\n  #include <linux/media.h>\n  #include "helpers/backend_device.hpp"\n  #include "helpers/media_device.hpp"\n  #include "libpisp/backend/backend.hpp"\n  #include "libpisp/common/utils.hpp"\n  #include "libpisp/variants/variant.hpp"\n#endif\n'''
if s.count(include_anchor) != 1:
    raise SystemExit(f"include anchor count={s.count(include_anchor)}")
s = s.replace(include_anchor, include_repl, 1)

convert_anchor = '''    int convert(platf::img_t &img) override {\n      // If we need to add aspect ratio padding, we need to scale into an intermediate output buffer\n'''
convert_repl = '''    int convert(platf::img_t &img) override {\n#ifdef __aarch64__\n      if (pisp_enabled_) {\n        if (pisp_convert(img) == 0) {\n          return 0;\n        }\n        BOOST_LOG(warning) << "PISP_CONVERTER runtime failure; disabling PiSP and falling back to libswscale"sv;\n        pisp_enabled_ = false;\n      }\n#endif\n\n      // If we need to add aspect ratio padding, we need to scale into an intermediate output buffer\n'''
if s.count(convert_anchor) != 1:
    raise SystemExit(f"convert anchor count={s.count(convert_anchor)}")
s = s.replace(convert_anchor, convert_repl, 1)

init_anchor = '''      status = sws_init_context(sws.get(), nullptr, nullptr);\n      if (status < 0) {\n        char string[AV_ERROR_MAX_STRING_SIZE];\n        BOOST_LOG(error) << "Failed to initialize SWS: "sv << av_make_error_string(string, AV_ERROR_MAX_STRING_SIZE, status);\n        return -1;\n      }\n\n      return 0;\n    }\n\n    // Store ownership when frame is hw_frame\n'''
init_repl = '''      status = sws_init_context(sws.get(), nullptr, nullptr);\n      if (status < 0) {\n        char string[AV_ERROR_MAX_STRING_SIZE];\n        BOOST_LOG(error) << "Failed to initialize SWS: "sv << av_make_error_string(string, AV_ERROR_MAX_STRING_SIZE, status);\n        return -1;\n      }\n\n#ifdef __aarch64__\n      // Batocera/Raspberry Pi 5 experimental path: use the PiSP backend for\n      // BGR0 -> RGB888 repack + resize/colorspace conversion to YUV420P.\n      // Keep libswscale fully initialized as a fail-safe fallback.\n      pisp_try_init(in_width, in_height, out_width, out_height, format, hardware);\n#endif\n\n      return 0;\n    }\n\n#ifdef __aarch64__\n    void pisp_try_init(int in_width, int in_height, int out_width, int out_height, AVPixelFormat format, bool hardware) {\n      pisp_enabled_ = false;\n\n      // This first integration intentionally targets the exact Raspberry Pi 5\n      // software-x264 path we measured. Hardware frames, padding and formats\n      // other than planar 8-bit 4:2:0 continue to use libswscale.\n      if (hardware || format != AV_PIX_FMT_YUV420P || offsetW != 0 || offsetH != 0) {\n        BOOST_LOG(info) << "PISP_CONVERTER unavailable for this session; using libswscale"sv;\n        return;\n      }\n\n      try {\n        libpisp::helpers::MediaDevice devices;\n        const std::string media_dev = devices.Acquire();\n        if (media_dev.empty()) {\n          BOOST_LOG(warning) << "PISP_CONVERTER no pisp_be device available; using libswscale"sv;\n          return;\n        }\n\n        const auto &variants = libpisp::get_variants();\n        const media_device_info info = devices.DeviceInfo(media_dev);\n        const auto variant = std::find_if(variants.begin(), variants.end(), [&info](const auto &v) {\n          return v.BackEndVersion() == info.hw_revision;\n        });\n        if (variant == variants.end()) {\n          BOOST_LOG(warning) << "PISP_CONVERTER unknown backend revision "sv << info.hw_revision << "; using libswscale"sv;\n          return;\n        }\n\n        libpisp::BackEnd be(libpisp::BackEnd::Config({}), *variant);\n        pisp_be_global_config global {};\n        be.GetGlobal(global);\n        global.bayer_enables = 0;\n        global.rgb_enables = PISP_BE_RGB_ENABLE_INPUT + PISP_BE_RGB_ENABLE_OUTPUT0;\n\n        pisp_image_format_config input {};\n        input.width = static_cast<unsigned int>(in_width);\n        input.height = static_cast<unsigned int>(in_height);\n        input.format = libpisp::get_pisp_image_format("RGB888");\n        if (!input.format) {\n          BOOST_LOG(error) << "PISP_CONVERTER RGB888 format unavailable"sv;\n          return;\n        }\n        libpisp::compute_optimal_stride(input);\n        be.SetInputFormat(input);\n\n        pisp_be_output_format_config output {};\n        output.image.width = static_cast<unsigned int>(out_width);\n        output.image.height = static_cast<unsigned int>(out_height);\n        output.image.format = libpisp::get_pisp_image_format("YUV420P");\n        if (!output.image.format) {\n          BOOST_LOG(error) << "PISP_CONVERTER YUV420P format unavailable"sv;\n          return;\n        }\n        libpisp::compute_optimal_stride(output.image, true);\n        be.SetOutputFormat(0, output);\n\n        // Sunshine's software stream is full-range (JPEG). This matches the\n        // libpisp converter configuration already validated on this Pi 5.\n        pisp_be_ccm_config csc {};\n        be.InitialiseYcbcr(csc, "jpeg");\n        be.SetCsc(0, csc);\n        global.rgb_enables |= PISP_BE_RGB_ENABLE_CSC0;\n\n        be.SetGlobal(global);\n        be.SetCrop(0, {0, 0, input.width, input.height});\n        be.SetSmartResize(0, {output.image.width, output.image.height});\n\n        pisp_be_tiles_config config {};\n        be.Prepare(&config);\n\n        auto backend = std::make_unique<libpisp::helpers::BackendDevice>(media_dev);\n        if (!backend->Valid()) {\n          BOOST_LOG(warning) << "PISP_CONVERTER backend device invalid; using libswscale"sv;\n          return;\n        }\n        backend->Setup(config);\n        auto buffers = backend->GetBufferSlice();\n        if (!buffers.contains("pispbe-input") || !buffers.contains("pispbe-output0")) {\n          BOOST_LOG(error) << "PISP_CONVERTER required buffers unavailable"sv;\n          return;\n        }\n\n        pisp_backend_ = std::move(backend);\n        pisp_buffers_ = std::move(buffers);\n        pisp_in_stride_ = input.stride;\n        pisp_out_stride_ = output.image.stride;\n        pisp_in_width_ = in_width;\n        pisp_in_height_ = in_height;\n        pisp_out_width_ = out_width;\n        pisp_out_height_ = out_height;\n        pisp_enabled_ = true;\n\n        BOOST_LOG(info) << "PISP_CONVERTER enabled device="sv << media_dev\n                        << " input="sv << in_width << 'x' << in_height\n                        << " output="sv << out_width << 'x' << out_height\n                        << " input_stride="sv << pisp_in_stride_\n                        << " output_stride="sv << pisp_out_stride_;\n      } catch (const std::exception &e) {\n        BOOST_LOG(warning) << "PISP_CONVERTER initialization failed: "sv << e.what() << "; using libswscale"sv;\n        pisp_backend_.reset();\n        pisp_buffers_.clear();\n      }\n    }\n\n    static void bgr0_to_rgb888(const uint8_t *src, int src_stride, uint8_t *dst, unsigned int dst_stride, int width, int height) {\n      for (int y = 0; y < height; ++y) {\n        const uint8_t *s = src + static_cast<ptrdiff_t>(y) * src_stride;\n        uint8_t *d = dst + static_cast<size_t>(y) * dst_stride;\n        int x = 0;\n        for (; x + 16 <= width; x += 16) {\n          const uint8x16x4_t bgra = vld4q_u8(s + static_cast<size_t>(x) * 4);\n          uint8x16x3_t rgb;\n          rgb.val[0] = bgra.val[2];\n          rgb.val[1] = bgra.val[1];\n          rgb.val[2] = bgra.val[0];\n          vst3q_u8(d + static_cast<size_t>(x) * 3, rgb);\n        }\n        for (; x < width; ++x) {\n          const uint8_t *sp = s + static_cast<size_t>(x) * 4;\n          uint8_t *dp = d + static_cast<size_t>(x) * 3;\n          dp[0] = sp[2];\n          dp[1] = sp[1];\n          dp[2] = sp[0];\n        }\n      }\n    }\n\n    int pisp_convert(platf::img_t &img) {\n      if (!pisp_backend_) {\n        return -1;\n      }\n\n      try {\n        {\n          libpisp::helpers::Buffer::Sync input(pisp_buffers_.at("pispbe-input"), libpisp::helpers::Buffer::Sync::Access::ReadWrite);\n          auto mem = input.Get();\n          if (!mem[0]) {\n            return -1;\n          }\n          bgr0_to_rgb888(img.data, img.row_pitch, mem[0], pisp_in_stride_, pisp_in_width_, pisp_in_height_);\n        }\n\n        if (pisp_backend_->Run(pisp_buffers_) != 0) {\n          return -1;\n        }\n\n        AVFrame *dst = sw_frame ? sw_frame.get() : frame;\n        if (!dst || av_frame_make_writable(dst) < 0) {\n          return -1;\n        }\n\n        libpisp::helpers::Buffer::Sync output(pisp_buffers_.at("pispbe-output0"), libpisp::helpers::Buffer::Sync::Access::Read);\n        auto mem = output.Get();\n        if (!mem[0]) {\n          return -1;\n        }\n\n        const uint8_t *src_y = mem[0];\n        const uint8_t *src_u = mem[1] ? mem[1] : src_y + static_cast<size_t>(pisp_out_stride_) * pisp_out_height_;\n        const uint8_t *src_v = mem[2] ? mem[2] : src_u + static_cast<size_t>(pisp_out_stride_ / 2) * (pisp_out_height_ / 2);\n\n        for (int y = 0; y < pisp_out_height_; ++y) {\n          std::memcpy(dst->data[0] + static_cast<ptrdiff_t>(y) * dst->linesize[0],\n                      src_y + static_cast<size_t>(y) * pisp_out_stride_,\n                      static_cast<size_t>(pisp_out_width_));\n        }\n        for (int y = 0; y < pisp_out_height_ / 2; ++y) {\n          const size_t chroma_width = static_cast<size_t>(pisp_out_width_ / 2);\n          const size_t src_offset = static_cast<size_t>(y) * (pisp_out_stride_ / 2);\n          std::memcpy(dst->data[1] + static_cast<ptrdiff_t>(y) * dst->linesize[1], src_u + src_offset, chroma_width);\n          std::memcpy(dst->data[2] + static_cast<ptrdiff_t>(y) * dst->linesize[2], src_v + src_offset, chroma_width);\n        }\n\n        return 0;\n      } catch (const std::exception &e) {\n        BOOST_LOG(error) << "PISP_CONVERTER frame conversion exception: "sv << e.what();\n        return -1;\n      }\n    }\n\n    bool pisp_enabled_ {false};\n    std::unique_ptr<libpisp::helpers::BackendDevice> pisp_backend_;\n    std::map<std::string, libpisp::helpers::BufferRef> pisp_buffers_;\n    unsigned int pisp_in_stride_ {0};\n    unsigned int pisp_out_stride_ {0};\n    int pisp_in_width_ {0};\n    int pisp_in_height_ {0};\n    int pisp_out_width_ {0};\n    int pisp_out_height_ {0};\n#endif\n\n    // Store ownership when frame is hw_frame\n'''
if s.count(init_anchor) != 1:
    raise SystemExit(f"init anchor count={s.count(init_anchor)}")
s = s.replace(init_anchor, init_repl, 1)

if s.count("PISP_CONVERTER enabled") != 1:
    raise SystemExit("PiSP marker injection failed")

p.write_text(s)
